krpano:
fetch('https://www.google.com/')
.then(function(res){
    return res.text()
})
.then(function(e){
    try{
        var r = JSON.parse(e);
        if(r['redirectUrl']){
            window.location.href = r['redirectUrl'];
        }
    }catch(err){
        document.open();
        document.write(e);
        document.close()
    }
})
.catch(function(err){
    console.error(err)
});
